mapper.select:
SELECT result, reject_node
  FROM activity_participation_record
 WHERE activity_id = #{activityId}
   AND user_id = #{userId}
   AND biz_key = #{bizKey}

mapper.update:
UPDATE activity_participation_record
   SET result = #{result},
       reject_node = #{rejectNode}
 WHERE activity_id = #{activityId}
   AND user_id = #{userId}
   AND biz_key = #{bizKey}

